import { VueRenderer } from '@tiptap/vue-3'
import tippy from 'tippy.js'

export default ({
	listComponent,
	items,
	command,
}) => ({
	items,
	command,
	render: () => {
		let component
		let popup

		return {
			onStart: (props) => {
				component = new VueRenderer(listComponent, {
					editor: props.editor,
					props: {
						...props,
						onSelect: () => popup.length > 0 && popup[0].hide(),
					},
				})

				if (!props.clientRect) {
					return
				}

				popup = tippy('body', {
					getReferenceClientRect: props.clientRect,
					appendTo: () => document.body,
					content: component.element,
					showOnCreate: true,
					interactive: true,
					trigger: 'manual',
					placement: 'bottom-start',
				})
			},

			onUpdate(props) {
				component.updateProps(props)

				if (!props.clientRect || !popup) {
					return
				}

				popup[0].setProps({
					getReferenceClientRect: props.clientRect,
				})
			},

			onKeyDown(props) {
				if (!popup) {
					return
				}

				if (props.event.key === 'Escape') {
					popup[0].hide()
					popup[0].destroy()
					component.destroy()
					popup = null

					return true
				}

				return component.ref?.onKeyDown?.(props)
			},

			onExit() {
				if (!popup) {
					return
				}
				popup[0].destroy()
				component.destroy()
			},
		}
	},
})
